--
-- Table structure for table `shipments`
--

CREATE TABLE `shipments` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `sender_id` bigint(20) UNSIGNED NOT NULL,
  `category_id` bigint(20) UNSIGNED DEFAULT NULL,
  `receiver_name` varchar(255) NOT NULL,
  `receiver_phone` varchar(255) DEFAULT NULL,
  `from_city` varchar(255) NOT NULL,
  `to_city` varchar(255) NOT NULL,
  `weight` decimal(8,2) NOT NULL,
  `description` text DEFAULT NULL,
  `product_images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`product_images`)),
  `travel_date` date DEFAULT NULL,
  `is_urgent` tinyint(1) NOT NULL DEFAULT 0,
  `status` enum('pending','accepted','in_transit','delivered') NOT NULL DEFAULT 'pending',
  `deal_status` varchar(255) NOT NULL DEFAULT 'pending',
  `inquiry_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `is_paused_by_inquiries` tinyint(1) NOT NULL DEFAULT 0,
  `approval_status` varchar(255) NOT NULL DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

