--
-- Table structure for table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `name` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `role` enum('sender','traveler') NOT NULL DEFAULT 'sender',
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `city` varchar(255) DEFAULT NULL,
  `country` varchar(255) NOT NULL DEFAULT 'UAE',
  `photo` text DEFAULT NULL,
  `id_document_type` varchar(32) DEFAULT NULL,
  `id_document_number` varchar(120) DEFAULT NULL,
  `id_document_path` varchar(255) DEFAULT NULL,
  `id_document_status` varchar(32) DEFAULT NULL,
  `id_document_comment` text DEFAULT NULL,
  `marketing_opt_in` tinyint(1) NOT NULL DEFAULT 0,
  `unsubscribe_token` varchar(64) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

